            stroke('h', -2, -5, -5, -11, 2, 1);
            stroke('h', 2, -5, 5, -11, 2, 1);
            stroke('d', -1, 6, -3, 11, 2, 1);
            stroke('d', 1, 6, 3, 11, 2, 1);
